<?php
require __DIR__.'/config.php';require __DIR__.'/database_upgrade.php';try{$pdo=db();apply_database_upgrade($pdo);}catch(Throwable $e){exit('System unavailable.');}if(!is_role('admin')){http_response_code(403);exit('Administrator access required.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$verified=(int)$_POST['verified'];$q=$pdo->prepare("SELECT owner_id,name FROM businesses WHERE id=? AND status='approved'");$q->execute([$id]);$b=$q->fetch();if($b){$pdo->prepare('UPDATE businesses SET is_verified=?,verified_at=? WHERE id=?')->execute([$verified,$verified?date('Y-m-d H:i:s'):null,$id]);notify_user($pdo,(int)$b['owner_id'],$verified?'Your business is now verified.':'Your business verification was removed.','owner.php','verification');audit($pdo,user()['id'],$verified?'Business verified':'Business unverified',$b['name']);flash('Verification status updated.');}redirect('verify_businesses.php');}
$rows=$pdo->query("SELECT b.*,u.name owner,c.name category FROM businesses b JOIN users u ON u.id=b.owner_id JOIN categories c ON c.id=b.category_id WHERE b.status='approved' ORDER BY b.is_verified,b.name")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business verification | Davao Local</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="admin.css"></head><body><main class="admin-main standalone"><a class="text-link" href="admin.php">← Admin dashboard</a><header class="admin-top"><div><p class="eyebrow">ADMINISTRATION</p><h1>Business verification</h1></div></header><?php if($f=take_flash()):?><div class="flash <?=e($f[1])?>"><?=e($f[0])?></div><?php endif?><section class="panel"><div class="table-wrap"><table><tr><th>Business</th><th>Owner</th><th>Category</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $b):?><tr><td><?=e($b['name'])?></td><td><?=e($b['owner'])?></td><td><?=e($b['category'])?></td><td><span class="status <?=$b['is_verified']?'approved':'pending'?>"><?=$b['is_verified']?'Verified':'Not verified'?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$b['id']?>"><input type="hidden" name="verified" value="<?=$b['is_verified']?0:1?>"><button class="button <?=$b['is_verified']?'light':'coral'?>"><?=$b['is_verified']?'Remove verification':'Verify business'?></button></form></td></tr><?php endforeach?></table></div></section></main></body></html>
